body.script:
//
(function(){'use strict';var base=document.getElementById('mm-config').getAttribute('data-api-base').replace(/\/$/,'');var grid=document.getElementById('mm-grid'),status=document.getElementById('mm-status'),detail=document.getElementById('mm-detail'),heading=document.getElementById('mm-section-title');
function el(tag,cls,text){var n=document.createElement(tag);if(cls)n.className=cls;if(text!==undefined&&text!==null)n.textContent=String(text);return n}function clear(n){while(n.firstChild)n.removeChild(n.firstChild)}function message(text,error){status.textContent=text;status.classList.toggle('mm-error',!!error);status.classList.remove('mm-hidden')}function configured(){if(base.indexOf('your-mediamatrix-app.example.com')>=0){message('Setup required: replace the data-api-base value in this Blogger XML with your deployed MediaMatrix HTTPS URL ending in /api/public.',true);return false}return true}
async function request(path,params){if(!configured())throw new Error('MediaMatrix API base is not configured.');var response=await fetch(base+path+'?'+new URLSearchParams(params||{}).toString(),{headers:{Accept:'application/json'},mode:'cors'});var data=await response.json();if(!response.ok)throw new Error(data.error&&data.error.message?data.error.message:'The request could not be completed.');return data}function image(path,width){return typeof path==='string'&&path.charAt(0)==='/'?'https://image.tmdb.org/t/p/'+(width||'w500')+path:''}
function card(media){var b=el('button','mm-card');b.type='button';b.setAttribute('aria-label','View details for '+media.title);var img=el('img','mm-poster');img.loading='lazy';img.alt=media.title+' poster';img.width=500;img.height=750;var src=image(media.posterPath);if(src)img.src=src;b.appendChild(img);b.appendChild(el('h3','',media.title));b.appendChild(el('p','',(media.releaseDate||'Date unavailable')+(media.rating?' · ★ '+Number(media.rating).toFixed(1):'')));b.addEventListener('click',function(){loadTitle(media.type,media.id)});return b}
function render(data){clear(grid);clear(detail);detail.classList.add('mm-hidden');grid.classList.remove('mm-hidden');var items=(data.results||[]).filter(function(m){return m.type==='movie'||m.type==='tv'});if(!items.length){message('No titles matched this request.');return}status.classList.add('mm-hidden');items.forEach(function(m){grid.appendChild(card(m))})}
async function discover(){if(!configured())return;var type=document.getElementById('mm-type').value;heading.textContent=type==='tv'?'Discover TV series':'Discover movies';grid.classList.add('mm-hidden');message('Loading real TMDB metadata…');try{render(await request('/discover',{type:type,page:1}))}catch(e){message(e.message,true)}}
async function search(q){if(!configured())return;heading.textContent='Results for “'+q+'”';grid.classList.add('mm-hidden');message('Searching…');try{render(await request('/search',{q:q,page:1}))}catch(e){message(e.message,true)}}
async function loadTitle(type,id){grid.classList.add('mm-hidden');detail.classList.add('mm-hidden');message('Loading details and official availability…');try{var data=await request('/title',{type:type,id:id}),m=data.media;clear(detail);status.classList.add('mm-hidden');detail.classList.remove('mm-hidden');var poster=el('img');poster.alt=m.title+' poster';poster.width=500;poster.height=750;var src=image(m.posterPath);if(src)poster.src=src;var body=el('div');body.appendChild(el('span','mm-eyebrow',type==='tv'?'TV series':'Movie'));body.appendChild(el('h2','',m.title));body.appendChild(el('p','mm-overview',m.overview||'No overview is available.'));var providers=el('div','mm-providers'),offers=data.availability&&Array.isArray(data.availability.offers)?data.availability.offers:[];offers.forEach(function(offer){if(!offer.url)return;var a=el('a','mm-provider','Watch on '+offer.providerName+' · '+offer.type+' ↗');try{var url=new URL(offer.url);if(url.protocol!=='https:'&&url.protocol!=='http:')return;a.href=url.href}catch(_){return}a.target='_blank';a.rel='noopener noreferrer';providers.appendChild(a)});if(providers.childNodes.length){body.appendChild(el('h3','','Official availability'));body.appendChild(providers)}else body.appendChild(el('p','mm-status',data.availability&&data.availability.configured?'No provider options were returned for the selected country.':'Streaming availability is not configured.'));var back=el('button','mm-button','Back to results');back.type='button';back.addEventListener('click',function(){detail.classList.add('mm-hidden');grid.classList.remove('mm-hidden')});body.appendChild(back);detail.appendChild(poster);detail.appendChild(body);detail.scrollIntoView({behavior:'smooth'})}catch(e){message(e.message,true);grid.classList.remove('mm-hidden')}}
document.getElementById('mm-search').addEventListener('submit',function(e){e.preventDefault();var q=document.getElementById('mm-query').value.trim();if(q.length>=2)search(q)});document.getElementById('mm-type').addEventListener('change',discover);discover()}());
//
